import sys
POINTS = {'A': 1, 'R': 1, 'O': 3, 'G': 3, 'B': 6}
def score(toss):
    rings = toss.rstrip('+')
    return sum(POINTS[c] for c in rings) + (len(rings) == 2) + 2 * toss.endswith('+')
lines = sys.stdin.read().splitlines()
n = int(lines[0])
results = []
for player, line in enumerate(lines[1:n + 1], 1):
    tosses = line.split()
    results.append((sum(score(t) for t in tosses), len(tosses), player))
results.sort(key=lambda item: (-item[0], item[1]))
print(*(f'{player}-{total}' for total, count, player in results))
